package dev.slithergoh.pixelmonradar.client.screen;
import dev.slithergoh.pixelmonradar.client.*;import net.minecraft.client.Minecraft;import net.minecraft.client.gui.GuiGraphics;import net.minecraft.client.gui.components.*;import net.minecraft.client.gui.screens.Screen;import net.minecraft.core.registries.BuiltInRegistries;import net.minecraft.network.chat.Component;import net.minecraft.resources.ResourceLocation;import net.minecraft.world.item.ItemStack;import net.minecraft.world.level.block.Block;import java.util.*;
public final class OreScreen extends Screen{private EditBox search;private List<ResourceLocation>blocks=List.of();private int scroll;private OreScanner.Category category=OreScanner.Category.USEFUL;private static final OreScanner.Category[]CATS=OreScanner.Category.values();public OreScreen(){super(Component.literal("Block ESP"));}@Override protected void init(){int l=width/2-240;search=new EditBox(font,l+12,73,260,22,Component.literal("Search blocks"));search.setHint(Component.literal("Search Pixelmon / Minecraft / modded blocks..."));addRenderableWidget(search);addRenderableWidget(Button.builder(Component.literal("ESP "+on(RadarSettings.oreEspEnabled)),b->{RadarSettings.oreEspEnabled=!RadarSettings.oreEspEnabled;b.setMessage(Component.literal("ESP "+on(RadarSettings.oreEspEnabled)));RadarSettings.save();}).bounds(l+278,73,80,22).build());addRenderableWidget(Button.builder(Component.literal("Range "+RadarSettings.oreRange+"m"),b->{RadarSettings.oreRange=RadarSettings.oreRange>=64?8:RadarSettings.oreRange+8;b.setMessage(Component.literal("Range "+RadarSettings.oreRange+"m"));RadarSettings.save();}).bounds(l+364,73,104,22).build());refresh();}private static String on(boolean v){return v?"ON":"OFF";}private void refresh(){blocks=OreScanner.candidates(category);scroll=0;}private List<ResourceLocation>filtered(){String q=search==null?"":search.getValue().toLowerCase();return blocks.stream().filter(x->x.toString().toLowerCase().contains(q)||name(x).toLowerCase().contains(q)).toList();}private String name(ResourceLocation id){ItemStack s=new ItemStack(BuiltInRegistries.BLOCK.get(id).asItem());return s.isEmpty()?id.getPath().replace('_',' '):s.getHoverName().getString();}@Override public void render(GuiGraphics g,int mx,int my,float pt){renderBackground(g,mx,my,pt);int l=width/2-240,r=l+480;g.fill(l,14,r,height-14,0xEC0D1720);g.fill(l,14,r,39,0xFF24465E);g.fill(l,39,r,66,0xFF162A39);g.drawString(font,"BLOCK ESP",l+12,23,0xFFFFFF,true);g.drawString(font,"Pixelmon world scanner",l+82,23,0x9EC6DA,false);for(int i=0;i<CATS.length;i++)drawTab(g,l+10+i*77,43,CATS[i],CATS[i]==category);super.render(g,mx,my,pt);List<ResourceLocation>a=filtered();int max=Math.max(1,(height-140)/42);scroll=Math.min(scroll,Math.max(0,a.size()-max));int y=105;for(int i=scroll;i<a.size()&&i<scroll+max;i++){ResourceLocation id=a.get(i);boolean s=RadarSettings.selectedOres.contains(id.toString());g.fill(l+10,y-3,r-10,y+34,s?0xFF285747:0xD017232D);Block b=BuiltInRegistries.BLOCK.get(id);ItemStack stack=new ItemStack(b.asItem());if(!stack.isEmpty())g.renderItem(stack,l+18,y+6);g.drawString(font,name(id),l+45,y+3,s?0xA9FFD4:0xFFFFFF,true);g.drawString(font,id.toString(),l+45,y+17,0x8298A5,false);g.drawString(font,s?"ON":"OFF",r-42,y+11,s?0x74FFAE:0x85949D,true);y+=42;}g.drawString(font,RadarSettings.selectedOres.size()+" active  •  click cards to toggle  •  wheel to scroll",l+12,height-27,0x91A9B6,false);}
 private void drawTab(GuiGraphics g,int x,int y,OreScanner.Category c,boolean active){g.fill(x,y,x+70,y+19,active?0xFF39708E:0xFF203541);String icon=switch(c){case USEFUL->"★";case ORES->"◆";case LOOT->"●";case PLANTS->"♣";case UTILITY->"⚙";case ALL->"▦";};g.drawCenteredString(font,icon+" "+shortName(c),x+35,y+6,active?0xFFFFFF:0xA8BDC8);}private String shortName(OreScanner.Category c){return switch(c){case USEFUL->"Best";case ORES->"Ores";case LOOT->"Loot";case PLANTS->"Plants";case UTILITY->"Utility";case ALL->"All";};}
 @Override public boolean mouseClicked(double mx,double my,int b){int l=width/2-240;for(int i=0;i<CATS.length;i++){int tx=l+10+i*77;if(mx>=tx&&mx<=tx+70&&my>=43&&my<=62){category=CATS[i];refresh();return true;}}List<ResourceLocation>a=filtered();int max=Math.max(1,(height-140)/42),y=105;if(mx>=l+10&&mx<=l+470)for(int i=scroll;i<a.size()&&i<scroll+max;i++,y+=42)if(my>=y-3&&my<=y+34){String id=a.get(i).toString();if(!RadarSettings.selectedOres.remove(id))RadarSettings.selectedOres.add(id);RadarSettings.save();return true;}return super.mouseClicked(mx,my,b);}@Override public boolean mouseScrolled(double mx,double my,double sx,double sy){List<ResourceLocation>a=filtered();int max=Math.max(1,(height-140)/42);scroll=Math.max(0,Math.min(Math.max(0,a.size()-max),scroll+(sy<0?1:-1)));return true;}@Override public void onClose(){RadarSettings.save();super.onClose();}@Override public boolean isPauseScreen(){return false;}}
